const result = $input.first().json;

if (!result.success) {
  throw new Error('查询失败');
}

if (result.count === 0) {
  throw new Error('未找到数据 - 可能是大整数精度问题');
}

// 检查返回的 aweme_id 是否完整
const awemeId = result.data[0].aweme_id;
const expectedEnd = '407';  // 正确的末尾

if (String(awemeId).endsWith(expectedEnd)) {
  console.log('✓ aweme_id 完整:', awemeId);
} else {
  console.warn('⚠️ aweme_id 精度丢失:', awemeId, '(应该以', expectedEnd, '结尾)');
}

return result.data.map(item => ({ json: item }));

// 如果 aweme_id 来自上游节点
const awemeId = $json.aweme_id || '7554322613938523407';

// 确保转为字符串
const awemeIdStr = String(awemeId);

return [{
  json: {
    db_path: "O:/ai/2025AIAgent/MediaCrawler/database/sqlite_tables.db",
    sql: "SELECT * FROM douyin_aweme WHERE aweme_id = ?",
    params: [awemeIdStr]  // 始终使用字符串
  }
}];

// 批量查询多个 aweme_id
const awemeIds = [
  '7554322613938523407',
  '7555301991056985378',
  '7561675205911940402'
];

// 使用 IN 子句
const placeholders = awemeIds.map(() => '?').join(',');
const sql = `SELECT * FROM douyin_aweme WHERE aweme_id IN (${placeholders})`;

return [{
  json: {
    db_path: "O:/ai/2025AIAgent/MediaCrawler/database/sqlite_tables.db",
    sql: sql,
    params: awemeIds  // 字符串数组
  }
}];
